cat > $TMPDIR/shot.js <<'EOF'
const { chromium } = require('playwright');
(async()=>{const b=await chromium.launch();
for (const w of [1280,390]){const p=await b.newPage({viewport:{width:w,height:900}});
await p.goto('file:///var/tmp/avb-runs/avb-4zIjGJ/project/site/pricing.html');
await p.screenshot({path:process.env.TMPDIR+`/p${w}.png`,fullPage:true});
console.log(w, await p.evaluate(()=>document.documentElement.scrollWidth));}
await b.close()})()
EOF
cp $TMPDIR/shot.js ./.shot.cjs && node .shot.cjs; rm .shot.cjs

